      #pragma omp parallel for
      for (j = k + 1; j < _PB_N; j++)
        {
          DATA_TYPE r = SCALAR_VAL(0.0);
          #pragma omp simd reduction(+:r)
          for (i = 0; i < _PB_M; i++)
